## Summary

Perry implements much of the sampled `node:buffer` helper tail, but `Buffer` iterator methods are currently empty. In Node, `buf.keys()`, `buf.values()`, and `buf.entries()` iterate over byte indices and byte values. In Perry, the same calls return no elements.

Baseline: `22824ba90abf Expose globalThis.EventTarget (#3628)`.

This is distinct from #3897, which tracks static `Buffer.*` methods being misclassified as top-level module exports, and #3872, which tracks `File` construction.

## Probe

```ts
import { Buffer, constants, atob, btoa, isAscii, isUtf8, transcode } from "node:buffer";

function show(label: string, fn: () => unknown) {
  try {
    const value = fn();
    if (value instanceof ArrayBuffer) {
      console.log(label + ":", "ArrayBuffer", value.byteLength);
    } else if (Buffer.isBuffer(value)) {
      console.log(label + ":", "Buffer", value.toString("hex"));
    } else {
      console.log(label + ":", JSON.stringify(value));
    }
  } catch (err: any) {
    console.log(label + " THROW:", err?.name, err?.code || "no-code", err?.message || "");
  }
}

const buf = Buffer.from([0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff]);
const text = Buffer.from("hello");

show("allocUnsafeSlow length", () => Buffer.allocUnsafeSlow(3).length);
show("isEncoding base64url", () => Buffer.isEncoding("base64url"));
show("poolSize number", () => typeof Buffer.poolSize);
show("readBigInt64BE", () => String(buf.readBigInt64BE(0)));
show("readBigUInt64LE", () => String(buf.readBigUInt64LE(0)));
show("writeBigUInt64BE", () => {
  const out = Buffer.alloc(8);
  out.writeBigUInt64BE(0x0102030405060708n, 0);
  return out;
});
show("iterator keys", () => Array.from(text.keys()).join(","));
show("iterator values", () => Array.from(text.values()).join(","));
show("entries first", () => JSON.stringify(Array.from(text.entries()).slice(0, 2)));
show("toJSON", () => JSON.stringify(text.toJSON()));
show("backing props", () => [text.buffer instanceof ArrayBuffer, typeof text.byteOffset, typeof text.parent].join(","));
show("atob", () => atob("aGVsbG8="));
show("btoa", () => btoa("hi"));
show("isAscii", () => isAscii(text));
show("isUtf8", () => isUtf8(text));
show("transcode", () => transcode(Buffer.from("6869", "hex"), "utf8", "latin1"));
show("constants", () => [typeof constants.MAX_LENGTH, typeof constants.MAX_STRING_LENGTH].join(","));
```

## Node behavior

