iterator keys: "0,1,2,3,4"
iterator values: "104,101,108,108,111"
entries first: "[[0,104],[1,101]]"
toJSON: "{\"type\":\"Buffer\",\"data\":[104,101,108,108,111]}"
backing props: "true,number,object"
atob: "hello"
btoa: "aGk="
isAscii: true
