import eventsDefault, * as events from "node:events";
import osDefault, * as os from "node:os";
import pathDefault, * as path from "node:path";
import querystringDefault, * as querystring from "node:querystring";
import urlDefault, * as url from "node:url";
import utilDefault, * as util from "node:util";

function shape(value: any): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return `array length=${value.length}`;
  const type = typeof value;
  if (type === "object") return `object keys=${Object.keys(value).slice(0, 8).join(",")}`;
  if (type === "function") return `function length=${value.length}`;
  return type;
}

function show(name: string, defaultValue: any, namespaceValue: any, expectedKey: string) {
  console.log(`${name} default:`, shape(defaultValue));
  console.log(`${name} namespace.default identity:`, namespaceValue.default === defaultValue);
  console.log(`${name} expected key:`, shape(defaultValue?.[expectedKey]), shape(namespaceValue[expectedKey]));
}

show("async_hooks", asyncHooksDefault, asyncHooks, "AsyncLocalStorage");
show("events", eventsDefault, events, "EventEmitter");
show("os", osDefault, os, "platform");
show("path", pathDefault, path, "join");
show("querystring", querystringDefault, querystring, "parse");
show("url", urlDefault, url, "URL");
show("util", utilDefault, util, "format");
```

